package rmcloud

import (
	"crypto/x509"
	"log/slog"
	"net/http"
)

//go:generate optgen generate --string-setter plain --source-file $GOFILE

// options is what [New] reads. The With options are generated by go-optgen;
// a nil argument keeps the default unless a field says otherwise.
type options struct {
	// endpoints are the auth host and, unless resolver replaces it, the sync
	// host. Token calls always use them. With the [Production] pair and no
	// resolver, sync and notifications follow discovery and the client
	// refuses private and loopback dials; any other pair is used as given,
	// and a server on the host's own network stays reachable.
	endpoints Endpoints `optgen:"default=Production()"`

	// resolver replaces discovery for sync and notifications. The auth host
	// still comes from endpoints. Absent means discovery; nil is ignored.
	resolver Hosts `optgen:"notnil"`

	// userAgent is the User-Agent on token, sync, and notification calls.
	// [WithUserAgent] sets it; see there.
	userAgent string `optgen:"manual"`
	// userAgentSet tells an empty User-Agent from an absent option.
	userAgentSet bool `opt:"-"`

	// deviceDesc is the device description sent at registration. An empty
	// value keeps [DeviceDescMac].
	deviceDesc string `optgen:"default=DeviceDescMac"`

	// roundTripper carries every request, the notification upgrade
	// included: a proxy, a custom TLS configuration, or a test server's
	// transport. Redirect handling, size ceilings, and the wire log stay
	// this client's, and the SSRF guard is off: it cannot see rt's dials.
	roundTripper http.RoundTripper `optgen:"notnil"`

	// rootCAs is trusted instead of the system pool, for a server signed by
	// the host's own authority. It covers every call and the notification
	// socket. A roundTripper brings its own TLS instead.
	rootCAs *x509.CertPool

	// logger receives the client's records, the wire log included. The
	// default is slog.Default as it stands when New runs: a warning, and the
	// wire log RMCLOUD_WIRE_LOG asks for, must not vanish unconfigured.
	logger *slog.Logger `optgen:"default=slog.Default()"`
}

// WithUserAgent sets the User-Agent on token, sync, and notification calls.
// An empty string omits the header. When the option is absent, [New] sends
// the User-Agent the service expects, built from this machine's macOS
// version, or no header when that version cannot be read.
func WithUserAgent(ua string) Option {
	return func(o *options) {
		o.userAgent = ua
		o.userAgentSet = true
	}
}
